from unittest import TestCase
from html.parser import HTMLParser
from mistune import create_markdown


class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []

    def handle_starttag(self, tag, attrs):
        block_tags = {'div', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'ul', 'ol', 'li', 'blockquote', 'pre', 'table', 'tr'}
        if self.stack and self.stack[-1] == 'p' and tag in block_tags:
            self.errors.append(f"Validation error: block/invalid tag <{tag}> inside <p>")
        self.stack.append(tag)

    def handle_endtag(self, tag):
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f"Validation error: mismatched end tag </{tag}>")


class TestNFR001MathValidation(TestCase):
    def test_inline_double_dollar_math_html_validation(self):
        """AC-NFR-001-1: Metric: HTML validation errors | Threshold: 0 validation errors on pages with inline double-dollar math | Conditions: Parsed output rendered in HTML document | Method: HTML parser inspection"""
        md = create_markdown(plugins=["math"])

        markdown_texts = [
            "Here is some text with $$x^2 + y^2 = z^2$$ inline math.",
            "$$a + b$$ is at the beginning of a paragraph.",
            "At the end of a paragraph: $$c + d$$",
            "Multiple expressions: $$1 + 1 = 2$$ and $$2 + 2 = 4$$ in one line.",
        ]

        for text in markdown_texts:
            html_output = md(text)
            full_doc = f"<!DOCTYPE html><html><head><title>Math Test</title></head><body>{html_output}</body></html>"

            # Verify that inline math is rendered as span.math, not div.math
            self.assertIn('<span class="math">', html_output)
            self.assertNotIn('<div class="math">', html_output)

            # HTML parser inspection for validation errors
            validator = HTMLValidator()
            validator.feed(full_doc)
            validator.close()

            self.assertEqual(
                validator.errors,
                [],
                f"HTML validation errors found for input {repr(text)}: {validator.errors} in HTML: {html_output}",
            )

